messages.content:
  1	// RUN: %dafny /compile:3 /spillTargetCode:2 /compileTarget:cpp "%s" > "%t"
  2	// RUN: %diff "%s.expect" "%t"
  3	
  4	newtype uint32 = i:int | 0 <= i < 0x100000000
  5	
  6	method returnANullArray() returns (a: array?<uint32>)
  7	  ensures a == null
  8	{
  9	  a := null;
 10	}
 11	
 12	method returnANonNullArray() returns (a: array?<uint32>)
 13	  ensures a != null
 14	  ensures a.Length == 5
 15	{
 16	  a := new uint32[5];
 17	  a[0] := 1;
 18	  a[1] := 2;
 19	  a[2] := 3;
 20	  a[3] := 4;
 21	  a[4] := 5;
 22	}
 23	
 24	method LinearSearch(a: array<uint32>, len:uint32, key: uint32) returns (n: uint32)
 25	  requires a.Length == len as int
 26	  ensures 0 <= n <= len && n != 0
 27	  ensures n == len || a[n] == key
 28	{
 29	  n := 0;
 30	  while n < len
 31	    invariant n <= len
 32	  {
 33	    if a[n] == key {
 34	      return;
 35	    }
 36	    n := n + 1;
 37	  }
 38	}
 39	
 40	method PrintArray<A>(a:array?<A>, len:uint32)
 41	  requires a != null ==> len as int == a.Length
 42	{
 43	  if (a == null) {
 44	    print "It's null\n";
 45	  } else {
 46	    var i:uint32 := 0;
 47	    while i < len {
 48	      print a[i], " ";
 49	      i := i + 1;
 50	    }
 51	    print "\n";
 52	  }
 53	}
 54	
 55	datatype ArrayDatatype = AD(ar: array<uint32>)
 56	
 57	method Main() {
 58	  var a := new uint32[23];
 59	  var i := 0;
 60	  while i < 23 {
 61	    a[i] := i;
 62	    i := i + 1;
 63	  }
 64	  PrintArray(a, 23);
 65	  var n := LinearSearch(a, 23, 17);
 66	  print n, "\n";
 67	  var s : seq<uint32> := a[..];
 68	  print s, "\n";
 69	  s := a[2..16];
 70	  print s, "\n";
 71	  s := a[20..];
 72	  print s, "\n";
 73	  s := a[..8];
 74	  print s, "\n";
 75	
 76	  // Conversion to sequence should copy elements (sequences are immutable!)
 77	  a[0] := 42;
 78	  print s, "\n";
 79	
 80	  PrintArray<uint32>(null, 0);
 81	
 82	  print "Null array:\n";
 83	  var a1 := returnANullArray();
 84	  PrintArray<uint32>(a1, 5);
 85	
 86	  print "Non-Null array:\n";
 87	  var a2 := returnANonNullArray();
 88	  PrintArray<uint32>(a2, 5);
 89	
 90	  print "Array in datatype:\n";
 91	  var someAr := new uint32[3];
 92	  someAr[0] := 1;
 93	  someAr[1] := 3;
 94	  someAr[2] := 9;
 95	  var ad := AD(someAr);
 96	  PrintArray<uint32>(ad.ar, 3);
 97	}
 98	
 99	
100

